theorem crossingOn_congr (C : CircularOrder n) {s t : Finset (Fin n)}
    (hst : s = t) (hs : s.card = 4) (ht : t.card = 4) :
    crossingOn C s hs = crossingOn C t ht

theorem representative_K_eq_of_related_right
    (C : Circular.CircularOrder n) {C' D' : Circular.CircularOrder n}
    (h : ReindexRelated C' D') : Circular.K C C' = Circular.K C D'

theorem boundary_circularInterval_oppositeEdgeSide
    [Fintype α] [DecidableEq α]
    (T : Tree.PhyloTree α) {u : Tree.FullTree α}
    (hu : IsSubtree u T.asFullTree) {word : List α}
    (hword : word ∈ T.boundaryProfile) :
    CircularInterval (Finset.univ \ u.leaves.toFinset) word

theorem boundary_linearInterval_edgeSide [Fintype α] [DecidableEq α]
    (T : Tree.PhyloTree α) {u : Tree.FullTree α}
    (hu : IsSubtree u T.asFullTree) {word : List α}
    (hword : word ∈ T.boundaryProfile) :
    LinearInterval u.leaves.toFinset word

theorem frontier_block_of_isSubtree {u t : Tree.FullTree α}
    (hut : IsSubtree u t) {word : List α}
    (hword : word ∈ t.frontierProfile) :
    ∃ middle, middle ∈ u.frontierProfile ∧
      ∃ before after, word = before ++ middle ++ after

theorem ProperSubtree.adj_boundary {t : Tree.FullTree α}
    (p : ProperSubtree t) {x y : TreeAdequacy.FullTree.Vertex t}
    (hx : p.Below x) (hy : ¬ p.Below y)
    (hxy : (TreeAdequacy.FullTree.graph t).Adj x y) :
    x = p.child ∧ y = p.parent

theorem ProperSubtree.below_of_reachable {t : Tree.FullTree α}
    (p : ProperSubtree t) {x : TreeAdequacy.FullTree.Vertex t}
    (hx : ((TreeAdequacy.FullTree.graph t).deleteEdges
      {s(p.parent, p.child)}).Reachable p.child x) : p.Below x

theorem ProperSubtree.map_adj {t : Tree.FullTree α}
    (p : ProperSubtree t) {x y : TreeAdequacy.FullTree.Vertex p.tree}
    (hxy : (TreeAdequacy.FullTree.graph p.tree).Adj x y) :
    (TreeAdequacy.FullTree.graph t).Adj (p.embed x) (p.embed y)

theorem ProperSubtree.reachable_of_below {t : Tree.FullTree α}
    (p : ProperSubtree t) {x : TreeAdequacy.FullTree.Vertex t}
    (hx : p.Below x) :
    ((TreeAdequacy.FullTree.graph t).deleteEdges {s(p.parent, p.child)}).Reachable
      p.child x

@[simp] theorem ProperSubtree.root_not_below {t : Tree.FullTree α}
    (p : ProperSubtree t) :
    ¬ p.Below (TreeAdequacy.FullTree.rootVertex t)

theorem label_mem_leaves (t : Tree.FullTree α)
    {x : TreeAdequacy.FullTree.Vertex t} {a : α}
    (hx : TreeAdequacy.FullTree.label? t x = some a) : a ∈ t.leaves

theorem EdgePosition.adj_boundary {T : Tree.PhyloTree α}
    (p : EdgePosition T) {x y : TreeAdequacy.PhyloTree.Vertex T}
    (hx : p.Below x) (hy : ¬ p.Below y)
    (hxy : (TreeAdequacy.PhyloTree.graph T).Adj x y) :
    x = p.child ∧ y = p.parent

theorem EdgePosition.below_of_reachable {T : Tree.PhyloTree α}
    (p : EdgePosition T) {x : TreeAdequacy.PhyloTree.Vertex T}
    (hx : ((TreeAdequacy.PhyloTree.graph T).deleteEdges
      {s(p.parent, p.child)}).Reachable p.child x) : p.Below x

theorem EdgePosition.map_adj {T : Tree.PhyloTree α}
    (p : EdgePosition T) {x y : TreeAdequacy.FullTree.Vertex p.tree}
    (hxy : (TreeAdequacy.FullTree.graph p.tree).Adj x y) :
    (TreeAdequacy.PhyloTree.graph T).Adj (p.embed x) (p.embed y)

theorem EdgePosition.reachable_of_below {T : Tree.PhyloTree α}
    (p : EdgePosition T) {x : TreeAdequacy.PhyloTree.Vertex T}
    (hx : p.Below x) :
    ((TreeAdequacy.PhyloTree.graph T).deleteEdges {s(p.parent, p.child)}).Reachable
      p.child x

@[simp] theorem EdgePosition.tree_inside {T : Tree.PhyloTree α}
    (p : FullTree.ProperSubtree T.crown) :
    (EdgePosition.inside p).tree = p.tree

theorem lower_bound_maxPairValue (f : T → T → ℕ) {B L : ℕ}
    (hB : ∀ a b, f a b ≤ B) {a b : T} (hL : L ≤ f a b) :
    L ≤ maxPairValue f

theorem maxPairValue_eq_zero_or_exists (f : T → T → ℕ) {B : ℕ}
    (hB : ∀ a b, f a b ≤ B) :
    maxPairValue f = 0 ∨ ∃ a b, maxPairValue f = f a b

theorem value_le_maxPairValue (f : T → T → ℕ) {B : ℕ}
    (hB : ∀ a b, f a b ≤ B) (a b : T) :
    f a b ≤ maxPairValue f

theorem asFullSubtree_isSubtree {T : Tree.PhyloTree α}
    (p : GraphQuartet.PhyloTree.EdgePosition T) :
    RibbonRestriction.IsSubtree (asFullSubtree p) T.asFullTree

@[simp] theorem asFullSubtree_leaves_toFinset {T : Tree.PhyloTree α}
    (p : GraphQuartet.PhyloTree.EdgePosition T) :
    (asFullSubtree p).leaves.toFinset = p.cluster

theorem cluster_circularInterval {T : Tree.PhyloTree α}
    (p : GraphQuartet.PhyloTree.EdgePosition T) {word : List α}
    (hword : word ∈ T.boundaryProfile) :
    RibbonRestriction.CircularInterval p.cluster word

theorem complement_circularInterval {T : Tree.PhyloTree α}
    (p : GraphQuartet.PhyloTree.EdgePosition T) {word : List α}
    (hword : word ∈ T.boundaryProfile) :
    RibbonRestriction.CircularInterval (Finset.univ \ p.cluster) word

theorem edgeSide_child_parent_eq_cluster {T : Tree.PhyloTree α}
    (p : GraphQuartet.PhyloTree.EdgePosition T) :
    edgeSide T p.child p.parent = p.cluster

theorem edgeSide_parent_child_eq_complement {T : Tree.PhyloTree α}
    (p : GraphQuartet.PhyloTree.EdgePosition T) :
    edgeSide T p.parent p.child = Finset.univ \ p.cluster

theorem tiedCollisionDihedralCount_eq_tiedDihedralCount {n : ℕ}
    (π : Equiv.Perm (Fin n)) :
    tiedCollisionDihedralCount π = tiedDihedralCount π

theorem measurableSet_successfulRankSet {n : ℕ}
    (π : Equiv.Perm (Fin n)) (f : Circular.StripSample n) :
    MeasurableSet (successfulRankSet π f)

theorem publishedPermutonInequality_implies_stepPermutonTheorem {n : ℕ}
    (hn : 4 ≤ n) (hpublished : PublishedPermutonInequality) :
    Circular.StepPermutonTheorem n

theorem card_common_wrong [DecidableEq α] {U : Finset α} {s t : α}
    (hU : U.card = 3) (hs : s ∈ U) (ht : t ∈ U) (hst : s ≠ t) :
    ((U.erase s) ∩ (U.erase t)).card = 1

theorem card_erase_topology [DecidableEq α] {U : Finset α} {s : α}
    (hU : U.card = 3) (hs : s ∈ U) :
    (U.erase s).card = 2
